<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useRouter } from "vue-router";
import { http } from "@/utils/http";

type Collection = { id: string; parentId?: string; name: string; type?: string; description?: string; createdAt?: string; updatedAt?: string; version?: number };
const router = useRouter();
const activeTab = ref("collections");
const items = ref<Collection[]>([]);
const loading = ref(false);
const error = ref("");
const dialog = ref(false);
const saving = ref(false);
const editDialog = ref(false);
const editing = ref<Collection | null>(null);
const editForm = ref({ name: "", description: "" });
const editTargetId = ref("");
const memberResourceId = ref("");
const members = ref<{ resourceId: string; position: number }[]>([]);
const memberLoading = ref(false);
const orderText = ref("");
const moveParentId = ref("");
const relationResourceId = ref("");
const relationRows = ref<{ id: string; targetResourceId: string; type: string; position: number }[]>([]);
const relationLoading = ref(false);
const relationType = ref("RELATED_TO");
const tags = ref<{ id: string; name: string; color?: string }[]>([]);
const tagResourceId = ref("");
const resourceTags = ref<{ id: string; name: string; color?: string }[]>([]);
const tagLoading = ref(false);
const tagForm = ref({ name: "", color: "" });
const form = ref({ name: "", description: "", parentId: "" });
const search = ref("");
const collectionType = ref("manual");
const visibility = ref("private");
const roots = computed(() => items.value.filter(item => !item.parentId));
const filteredItems = computed(() => items.value.filter(item => item.name.toLowerCase().includes(search.value.trim().toLowerCase())));

async function load() {
  loading.value = true; error.value = "";
  try { const result = await http.get<unknown, unknown>("/collections"); items.value = Array.isArray(result) ? result as Collection[] : []; }
  catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "集合加载失败"; }
  finally { loading.value = false; }
}
async function createCollection() {
  if (!form.value.name.trim()) { error.value = "集合名称不能为空"; return; }
  saving.value = true;
  try { await http.post("/collections", { data: { name: form.value.name.trim(), description: form.value.description || null, parentId: form.value.parentId || null, type: collectionType.value, visibility: visibility.value } }); dialog.value = false; form.value = { name: "", description: "", parentId: "" }; await load(); }
  catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "集合创建失败"; }
  finally { saving.value = false; }
}
function openDetail(item: Collection) { router.push({ path: "/resource-center/collections", query: { id: item.id } }); }
function beginEdit(item: Collection) { editing.value = item; editForm.value = { name: item.name, description: item.description || "" }; editDialog.value = true; }
function editSelected() { const item = items.value.find(value => value.id === editTargetId.value); if (item) beginEdit(item); }
async function loadMembers() { if (!editTargetId.value) { members.value = []; orderText.value = ""; return; } memberLoading.value = true; try { const result = await http.get<unknown, unknown>(`/collections/${editTargetId.value}/resources`); members.value = Array.isArray(result) ? result as { resourceId: string; position: number }[] : []; orderText.value = members.value.map(item => item.resourceId).join(","); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "集合成员加载失败"; } finally { memberLoading.value = false; } }
async function addMember() { if (!editTargetId.value || !memberResourceId.value.trim()) { error.value = "请选择集合并输入 Resource ID"; return; } try { await http.post(`/collections/${editTargetId.value}/resources/${memberResourceId.value.trim()}`, { params: { position: members.value.length } }); memberResourceId.value = ""; await loadMembers(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "资源加入集合失败"; } }
async function removeMember(resourceId: string) { if (!editTargetId.value) return; try { await http.request("delete", `/collections/${editTargetId.value}/resources/${resourceId}`); await loadMembers(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "资源移出集合失败"; } }
async function reorderMembers() { if (!editTargetId.value) return; const resourceIds = orderText.value.split(",").map(value => value.trim()).filter(Boolean); if (!resourceIds.length) { error.value = "请输入完整的 Resource ID 顺序"; return; } try { await http.request("put", `/collections/${editTargetId.value}/resources/order`, { data: { resourceIds } }); await loadMembers(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "资源顺序保存失败"; } }
async function moveSelected() { if (!editTargetId.value) return; try { await http.post(`/collections/${editTargetId.value}/move`, { params: moveParentId.value ? { parentId: moveParentId.value } : undefined }); moveParentId.value = ""; await load(); } catch (e: any) { error.value = e?.response?.status === 409 ? "集合层级移动会形成循环，请选择其他父集合。" : e?.response?.data?.detail || e?.message || "集合移动失败"; } }
async function deleteSelected() { if (!editTargetId.value) return; const item = items.value.find(value => value.id === editTargetId.value); if (!window.confirm(`确认删除集合“${item?.name || editTargetId.value}”？集合成员关系会删除，但 Resource 会保留。`)) return; try { await http.request("delete", `/collections/${editTargetId.value}`); editTargetId.value = ""; members.value = []; orderText.value = ""; await load(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "集合删除失败"; } }
async function updateCollection() { if (!editing.value || !editForm.value.name.trim()) { error.value = "集合名称不能为空"; return; } saving.value = true; try { await http.request("put", `/collections/${editing.value.id}`, { data: { name: editForm.value.name.trim(), description: editForm.value.description || null }, headers: { "If-Match": `"${editing.value.version ?? 0}"` } }); editDialog.value = false; await load(); } catch (e: any) { error.value = e?.response?.status === 409 ? "集合已被其他请求修改，请刷新后重试。" : e?.response?.data?.detail || e?.message || "集合更新失败"; } finally { saving.value = false; } }
async function loadRelations() { if (!relationResourceId.value.trim()) { relationRows.value = []; return; } relationLoading.value = true; try { const result = await http.get<unknown, unknown>(`/resources/${relationResourceId.value.trim()}/relations`); relationRows.value = Array.isArray(result) ? result as { id: string; targetResourceId: string; type: string; position: number }[] : []; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "资源关系加载失败"; } finally { relationLoading.value = false; } }
async function createRelation() { const sourceId = relationResourceId.value.trim(); if (!sourceId || !memberResourceId.value.trim()) { error.value = "请输入来源 Resource ID 和目标 Resource ID"; return; } try { await http.post(`/resources/${sourceId}/relations`, { data: { targetResourceId: memberResourceId.value.trim(), type: relationType.value, position: relationRows.value.length } }); memberResourceId.value = ""; await loadRelations(); } catch (e: any) { error.value = e?.response?.status === 409 ? "不能创建自关联或重复关系。" : e?.response?.data?.detail || e?.message || "资源关系创建失败"; } }
async function removeRelation(row: { id: string }) { if (!relationResourceId.value.trim()) return; try { await http.request("delete", `/resources/${relationResourceId.value.trim()}/relations/${row.id}`); await loadRelations(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "资源关系删除失败"; } }
async function loadTags() { tagLoading.value = true; try { const result = await http.get<unknown, unknown>("/tags", { params: { page: 0, size: 100 } }); const page = result as { items?: unknown[]; content?: unknown[] }; tags.value = (Array.isArray(result) ? result : page?.items || page?.content || []) as { id: string; name: string; color?: string }[]; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "标签目录加载失败"; } finally { tagLoading.value = false; } }
async function loadResourceTags() { if (!tagResourceId.value.trim()) { resourceTags.value = []; return; } tagLoading.value = true; try { const result = await http.get<unknown, unknown>(`/resources/${tagResourceId.value.trim()}/tags`); resourceTags.value = Array.isArray(result) ? result as { id: string; name: string; color?: string }[] : []; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "资源标签加载失败"; } finally { tagLoading.value = false; } }
async function addTag() { const resourceId = tagResourceId.value.trim(); if (!resourceId || !tagForm.value.name.trim()) { error.value = "请输入 Resource ID 和标签名称"; return; } try { await http.post(`/resources/${resourceId}/tags`, { data: { name: tagForm.value.name.trim(), color: tagForm.value.color || null } }); tagForm.value = { name: "", color: "" }; await Promise.all([loadTags(), loadResourceTags()]); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "添加标签失败"; } }
async function removeTag(tag: { id: string }) { const resourceId = tagResourceId.value.trim(); if (!resourceId) return; try { await http.request("delete", `/resources/${resourceId}/tags/${tag.id}`); await Promise.all([loadTags(), loadResourceTags()]); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "删除标签失败"; } }
onMounted(load);
</script>

<template>
  <main class="p-4 md:p-6">
    <div class="flex justify-between items-start gap-4 mb-6"><div><h1 class="text-2xl font-semibold">集合</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">用逻辑集合组织资源，不改变附件的物理存储位置。</p></div><div class="flex gap-2"><el-button @click="dialog = true">新建集合</el-button><el-button :loading="loading" @click="load">刷新</el-button></div></div>
    <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4" /><div class="flex flex-wrap gap-2 mb-4"><el-select v-model="editTargetId" clearable placeholder="选择集合" class="w-64" @change="loadMembers"><el-option v-for="item in items" :key="item.id" :label="item.name" :value="item.id" /></el-select><el-button :disabled="!editTargetId" @click="editSelected">编辑所选集合</el-button><el-input v-model="memberResourceId" placeholder="Resource ID" class="w-64" /><el-button type="primary" :disabled="!editTargetId" @click="addMember">加入集合</el-button><el-input v-model="orderText" placeholder="按 Resource ID 调整顺序（逗号分隔）" class="w-96" /><el-button :disabled="!editTargetId" @click="reorderMembers">保存顺序</el-button><el-select v-model="moveParentId" clearable placeholder="移动到父集合" class="w-56"><el-option v-for="item in items.filter(value => value.id !== editTargetId)" :key="item.id" :label="item.name" :value="item.id" /></el-select><el-button :disabled="!editTargetId" @click="moveSelected">移动集合</el-button><el-button type="danger" plain :disabled="!editTargetId" @click="deleteSelected">删除集合</el-button></div>
    <el-tabs v-model="activeTab" class="mb-4"><el-tab-pane label="集合" name="collections" /><el-tab-pane label="标签" name="tags" /><el-tab-pane label="关系类型关系浏览器" name="relations" /></el-tabs>
    <template v-if="activeTab === 'collections'"><div class="flex flex-wrap gap-3 mb-4"><el-input v-model="search" clearable placeholder="搜索集合名称" class="w-64"/><el-select v-model="collectionType" class="w-32"><el-option label="全部类型" value="all"/><el-option label="手动" value="manual"/><el-option label="动态" value="dynamic"/></el-select><el-button @click="load">应用筛选</el-button></div><el-skeleton v-if="loading" :rows="8" animated /><el-card v-else shadow="never"><el-empty v-if="!filteredItems.length" description="暂无匹配集合，先创建一个集合吧" /><el-table v-else :data="filteredItems" stripe><el-table-column prop="name" label="名称" min-width="220"><template #default="{ row }"><el-button link type="primary" @click="openDetail(row)">{{ row.name }}</el-button></template></el-table-column><el-table-column label="类型" width="110"><template #default="{ row }">{{ row.type === 'dynamic' ? '动态' : '手动' }}</template></el-table-column><el-table-column label="Resource 数量" width="140">—</el-table-column><el-table-column label="所有者" width="140">当前用户</el-table-column><el-table-column label="可见性" width="120">私有</el-table-column><el-table-column prop="updatedAt" label="最近更新" min-width="180" /><el-table-column label="操作" width="100"><template #default="{ row }"><el-button link @click="openDetail(row)">详情</el-button></template></el-table-column></el-table></el-card></template>
    <el-card v-if="activeTab === 'collections' && editTargetId" shadow="never" class="mt-4"><template #header>集合成员</template><el-skeleton v-if="memberLoading" :rows="3" animated /><el-empty v-else-if="!members.length" description="暂无 Resource 成员" /><el-table v-else :data="members" stripe><el-table-column prop="resourceId" label="Resource ID" min-width="300" /><el-table-column prop="position" label="位置" width="100" /><el-table-column label="操作" width="100"><template #default="{ row }"><el-button link type="danger" @click="removeMember(row.resourceId)">移除</el-button></template></el-table-column></el-table></el-card><el-card v-else-if="activeTab === 'tags'" shadow="never"><template #header><div class="flex justify-between items-center"><span>标签目录与资源标签</span><el-button :loading="tagLoading" @click="loadTags">刷新标签目录</el-button></div></template><div class="flex flex-wrap gap-3 mb-4"><el-input v-model="tagResourceId" placeholder="Resource ID" class="w-72"/><el-input v-model="tagForm.name" placeholder="标签名称" class="w-52"/><el-input v-model="tagForm.color" placeholder="颜色（可选）" class="w-44"/><el-button type="primary" @click="addTag">添加标签</el-button><el-button @click="loadResourceTags">加载资源标签</el-button></div><el-divider content-position="left">当前资源标签</el-divider><el-skeleton v-if="tagLoading" :rows="3" animated/><el-empty v-else-if="!resourceTags.length" description="暂无资源标签"/><el-table v-else :data="resourceTags" stripe><el-table-column prop="name" label="Tag 名称" min-width="220"/><el-table-column prop="color" label="颜色" width="160"/><el-table-column label="操作" width="100"><template #default="{ row }"><el-button link type="danger" @click="removeTag(row)">移除</el-button></template></el-table-column></el-table><el-divider content-position="left">已使用标签目录</el-divider><el-empty v-if="!tags.length" description="暂无已使用标签"/><el-table v-else :data="tags" stripe><el-table-column prop="name" label="Tag 名称" min-width="220"/><el-table-column prop="color" label="颜色" width="160"/></el-table></el-card><el-card v-else shadow="never"><div class="flex flex-wrap gap-3 mb-4"><el-input v-model="relationResourceId" placeholder="来源 Resource ID" class="w-72"/><el-select v-model="relationType" class="w-52"><el-option v-for="type in ['CONTAINS','PART_OF','PREQUEL_TO','SEQUEL_TO','ADAPTATION_OF','VERSION_OF','DERIVED_FROM','RELATED_TO']" :key="type" :label="type" :value="type"/></el-select><el-input v-model="memberResourceId" placeholder="目标 Resource ID" class="w-72"/><el-button type="primary" @click="createRelation">创建关系</el-button><el-button @click="loadRelations">加载关系</el-button></div><el-skeleton v-if="relationLoading" :rows="4" animated/><el-empty v-else-if="!relationRows.length" description="暂无出向关系"/><el-table v-else :data="relationRows" stripe><el-table-column prop="targetResourceId" label="目标 Resource ID" min-width="300"/><el-table-column prop="type" label="关系类型" width="180"/><el-table-column prop="position" label="位置" width="100"/><el-table-column label="操作" width="100"><template #default="{ row }"><el-button link type="danger" @click="removeRelation(row)">删除</el-button></template></el-table-column></el-table></el-card>
    <el-dialog v-model="dialog" title="新建集合" width="520px"><el-form label-position="top"><el-form-item label="名称" required><el-input v-model="form.name" maxlength="256" show-word-limit /></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea" maxlength="2000" show-word-limit /></el-form-item><el-form-item label="类型"><el-radio-group v-model="collectionType"><el-radio value="manual">手动</el-radio><el-radio value="dynamic">动态</el-radio></el-radio-group></el-form-item><el-form-item label="父集合"><el-select v-model="form.parentId" clearable placeholder="无（顶级集合）" class="w-full"><el-option v-for="item in roots" :key="item.id" :label="item.name" :value="item.id" /></el-select></el-form-item><el-form-item label="可见性"><el-select v-model="visibility" class="w-full"><el-option label="私有" value="private"/><el-option label="共享" value="shared"/></el-select></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="createCollection">创建</el-button></template></el-dialog><el-dialog v-model="editDialog" title="编辑集合" width="520px"><el-form label-position="top"><el-form-item label="名称" required><el-input v-model="editForm.name" maxlength="256" /></el-form-item><el-form-item label="描述"><el-input v-model="editForm.description" type="textarea" maxlength="2000" /></el-form-item></el-form><template #footer><el-button @click="editDialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="updateCollection">保存</el-button></template></el-dialog>
  </main>
</template>
